examples += EXAMPLE(3, ('Intermediate', 'Trung bình'), ('Distance', 'Khoảng cách'), T('Find \\(AB\\) for \\(A(1;2;-1)\\), \\(B(3;6;3)\\).', 'Tính \\(AB\\) với \\(A(1;2;-1)\\), \\(B(3;6;3)\\).'),
  T('First \\(\\overrightarrow{AB}\\), then its length.', 'Tìm \\(\\overrightarrow{AB}\\) trước, rồi tính độ dài.'), [T('\\(\\overrightarrow{AB}=(2;4;4)\\).', '\\(\\overrightarrow{AB}=(2;4;4)\\).'), T('\\(AB=\\sqrt{4+16+16}=\\sqrt{36}\\).', '\\(AB=\\sqrt{4+16+16}=\\sqrt{36}\\).')], T('\\(AB=6\\).', '\\(AB=6\\).'))
