BOX1 = dict(BOXF); BOX1['points'] = dict(BOXF['points']); BOX1['points']['I'] = (2, 1.5, 1); BOX1['solid'] = ['O', 'A', 'B', 'C', 'O′', 'A′', 'B′', 'C′']; BOX1['segments'] = list(BOXF['segments']) + [['O', 'B′', {'color': '#c2410c', 'width': 3.6}]]
