def lvl(P):
    M = P['M']; a, b, c = M; kind = P['kind']; A, B = P['A'], P['B']; d = P['d']; C = P['C']
    out = {'Oxy': (a, b, 0), 'Oyz': (0, b, c), 'Oxz': (a, 0, c)}[kind]
    o1 = M4(1, 'The projection of \\(M%s\\) onto the plane \\((%s)\\) is…' % (P3(M), kind), 'Hình chiếu vuông góc của \\(M%s\\) lên mặt phẳng \\((%s)\\) là…' % (P3(M), kind), P3(out), [P3((a, b, c * -1)), P3((-a, -b, 0)) if kind == 'Oxy' else P3((0, -b, -c)), P3(M), P3((b, a, 0))], 'Set the missing coordinate to 0.', 'Cho tọa độ còn thiếu bằng 0.')
    r = tuple(y - x for x, y in zip(A, B)); assert math.isqrt(sum(t * t for t in r)) == d and d * d == sum(t * t for t in r)
    o2 = M4(2, '\\(A%s\\), \\(B%s\\). Then \\(AB=\\)…' % (P3(A), P3(B)), 'Cho \\(A%s\\), \\(B%s\\). Khi đó \\(AB=\\)…' % (P3(A), P3(B)), str(d), [str(d + 1), str(d - 1), str(sum(abs(t) for t in r)), str(d * d)], '\\(AB=\\sqrt{%d}=%d\\).' % (d * d, d), '\\(AB=\\sqrt{%d}=%d\\).' % (d * d, d))
    G = tuple(sum(p[i] for p in (A, B, C)) // 3 for i in range(3)); assert all(sum(p[i] for p in (A, B, C)) % 3 == 0 for i in range(3))
    o3 = M4(3, '\\(A%s\\), \\(B%s\\), \\(C%s\\). The centroid of \\(ABC\\) is…' % (P3(A), P3(B), P3(C)), 'Cho \\(A%s\\), \\(B%s\\), \\(C%s\\). Trọng tâm tam giác \\(ABC\\) là…' % (P3(A), P3(B), P3(C)), P3(G), [P3(tuple(sum(p[i] for p in (A, B, C)) for i in range(3))), P3(tuple(g + 1 for g in G)), P3(tuple(g - 1 for g in G))], 'Average the coordinates.', 'Lấy trung bình cộng từng tọa độ.')
    sym = P['sym']; sg = {'O': (-1, -1, -1), 'Oxy': (1, 1, -1), 'Oz': (-1, -1, 1)}[sym]; N = tuple(s * x for s, x in zip(sg, M)); claim = N if P['tv'][0] else (N[0], N[1], N[2] + 1)
    nm = {'O': 'the origin \\(O\\)', 'Oxy': 'the plane \\((Oxy)\\)', 'Oz': 'the axis \\(Oz\\)'}[sym]; nv = {'O': 'gốc \\(O\\)', 'Oxy': 'mặt phẳng \\((Oxy)\\)', 'Oz': 'trục \\(Oz\\)'}[sym]
    t4 = tf(4, 'The point symmetric to \\(M%s\\) about %s is \\(%s\\).' % (P3(M), nm, P3(claim)), 'Điểm đối xứng với \\(M%s\\) qua %s là \\(%s\\).' % (P3(M), nv, P3(claim)), P['tv'][0], 'The correct point is \\(%s\\).' % P3(N), 'Điểm đúng là \\(%s\\).' % P3(N))
    ax = P['ax']; pt = [0, 0, 0]; pt[ax[0]] = 3; pt[ax[1]] = -2; on = P['tv'][1]
    if not on: pt[ax[2]] = 1
    plane = 'Oxyz'[0] ; names = 'xyz'; pl = '(O%s%s)' % (names[ax[0]], names[ax[1]])
    t5 = tf(5, 'The point \\(N%s\\) lies in the plane \\(%s\\).' % (P3(tuple(pt)), pl), 'Điểm \\(N%s\\) thuộc mặt phẳng \\(%s\\).' % (P3(tuple(pt)), pl), on, 'A point of \\(%s\\) has the third coordinate 0.' % pl, 'Điểm thuộc \\(%s\\) có tọa độ thứ ba bằng 0.' % pl)
    s6 = sh(6, '\\(A%s\\), \\(B%s\\). Find \\(AB\\).' % (P3(P['A2']), P3(P['B2'])), 'Cho \\(A%s\\), \\(B%s\\). Tính \\(AB\\).' % (P3(P['A2']), P3(P['B2'])), P['d2'], '\\(AB=\\sqrt{(x_B-x_A)^2+\\dots}=%d\\).' % P['d2'], '\\(AB=\\sqrt{(x_B-x_A)^2+\\dots}=%d\\).' % P['d2'])
    assert sum((y - x) ** 2 for x, y in zip(P['A2'], P['B2'])) == P['d2'] ** 2
    D = P['D']; A3, B3, C3 = P['PA'], P['PB'], P['PC']; assert all(D[i] == A3[i] + C3[i] - B3[i] for i in range(3))
    s7 = sh(7, '\\(ABCD\\) is a parallelogram, \\(A%s\\), \\(B%s\\), \\(C%s\\). Find the \\(z\\)-coordinate of \\(D\\).' % (P3(A3), P3(B3), P3(C3)), 'Cho hình bình hành \\(ABCD\\) có \\(A%s\\), \\(B%s\\), \\(C%s\\). Tìm cao độ của \\(D\\).' % (P3(A3), P3(B3), P3(C3)), D[2], '\\(z_D=z_A+z_C-z_B=%d\\).' % D[2], '\\(z_D=z_A+z_C-z_B=%d\\).' % D[2])
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
def mk(M, kind, A, d, G, sym, tv, ax, A2, B2, d2, PA, PB, PC):
    B = tuple(x + y for x, y in zip(A, d[0])); C = tuple(3 * g - a - b for g, a, b in zip(G, A, B)); D = tuple(x + z - y for x, y, z in zip(PA, PB, PC))
    return dict(M=M, kind=kind, A=A, B=B, d=d[1], C=C, sym=sym, tv=tv, ax=ax, A2=A2, B2=B2, d2=d2, PA=PA, PB=PB, PC=PC, D=D)
